# Mochiichao — locked run, v3 (2026-10-28, HORSEPOWER PROGRAMME).
# ONE lane-agnostic runner for the parity locked job: the SAME file runs
# on Kaggle (kernel script; weights from the attached datasets) and on
# Colab / a plain GPU box (weights from Hugging Face; entry:
# `python3 locked_run_kernel_v3.py` or %run in a Colab cell). It runs
# workflow-turbo-fixed.json (Wan 2.2 TI2V-5B + Turbo LoRA + non-scaled
# UMT5), workflow-i2v-locked.json (native Wan 2.1 VACE-1.3B, reference
# control ENGAGED) and its negative control, for ONE character:
# Dorowani, Water Orb charge. Every output is gated by frame1_gate.py;
# a clip without its packet is not a result.
#
# v3 changes vs v2 (v2 result: preflight PASS; turbo FAILED with a
# WanVideoSampler 96-vs-48 channel RuntimeError; locked + control clips
# produced but the frame-1 gate returned fail-cannot-measure because the
# canon cutouts were missing at the gate's hard-coded home-relative
# path; see parity/PARITY-REPORT.md):
#   (a) GATE CUTOUTS SHIP INSIDE THE JOB (bug 1 fix): the canon cutouts
#       (show/production/canon-cutouts/{dorowani,wispkin}.png, sha256
#       pinned below) are embedded in this file, written at staging to
#       {JOB}/canon-cutouts/ AND to the exact legacy path likeness_gate
#       reads by default (~/workspace/mochiichao-show/canon-cutouts),
#       and the gate is invoked with --cutouts pointing at the job copy.
#       The job never again depends on a runner-side workspace path.
#   (b) TURBO CHANNEL FIX (bug 2 fix): workflow-turbo-fixed.json now
#       conditions the TI2V-5B the vendor's way — WanVideoEncode ->
#       WanVideoEmptyEmbeds.extra_latents (first-frame latent injection)
#       instead of WanVideoImageToVideoEncode, whose y latent the model
#       channel-concats onto the 48-channel noise (96 into in_dim 48).
#       preflight.py gained the channel-contract check, so this class
#       aborts BEFORE GPU time; the extended preflight is embedded here
#       and always wins over a stale dataset copy (drift is logged).
#   (c) SELF-CONTAINED JOB: every code/workflow/image asset the job
#       needs is embedded (base64) — datasets, when present, supply the
#       same files and win for everything EXCEPT the two v3-fixed files
#       in (b); per-file source + sha256 land in the run report.
#   (d) PINNED UPSTREAMS: ComfyUI and ComfyUI-WanVideoWrapper are
#       cloned at pinned commits (v1/v2 floated HEAD, so the wrapper
#       version that ran was never recorded); the pins are asserted
#       and recorded in the report.
#   (e) TIMINGS: staging, preflight, server boots and per-graph seconds
#       are all recorded, so lanes can be compared on measurements.
# Preflight strictness and gate thresholds are UNCHANGED from v1/v2
# (the channel-contract check is additive).
import subprocess, sys, os, json, time, shutil, glob, hashlib, traceback, base64
import urllib.request
from pathlib import Path

# ---------- lane detection ----------
def detect_lane():
    if os.environ.get('LOCKED_RUN_WORKDIR'):
        return 'generic', Path(os.environ['LOCKED_RUN_WORKDIR'])
    if os.path.isdir('/kaggle/working'):
        return 'kaggle', Path('/kaggle/working')
    if os.path.isdir('/content'):
        return 'colab', Path('/content/locked-run')
    return 'generic', Path.cwd() / 'locked-run-work'

LANE, WORKP = detect_lane()
WORK = str(WORKP)
OUT = f'{WORK}/out'
os.makedirs(OUT, exist_ok=True)
REPORT = {'kernel': 'marsfmmg/mochiichao-locked-run', 'kernel_version': 'v3',
          'lane': LANE, 'phases': {}, 'staging': {}, 'timings': {}}
REPORT_PATH = f'{OUT}/run-report.json'
GRAPH_TIMEOUT = 4 * 3600  # per-graph wait limit (unchanged from v2)
PROGRESS_EVERY = 30       # seconds between progress flushes while waiting
CURRENT_LOG = {'path': None}  # live comfy log of the running server
COMFYUI_PIN = 'c7bd15c28213348d72042ba0675747f1ebbed95f'
WRAPPER_PIN = '088128b224242e110d3906c6750e9a3a348a659b'

# ---------- embedded job assets (v3: the job carries its own files) ----------
# sha256 pins for the canon cutouts = repo show/production/canon-cutouts/.
CUTOUT_SHA = {
    'dorowani.png': 'a255fbb00af9c0eda45fb28aee1251302968d88f4b89f19f84b173f93b536cbf',
    'wispkin.png': 'b9de2318eb399094ad57fb6e21a388b05601a67425f18f49ff6a5b6408da0523',
}
EMBED_B64 = {
    'canon-cutouts/dorowani.png': '',
    'canon-cutouts/wispkin.png': '',
    'dorowani_start_tight.png': '',
    'wispkin_start_tight.png': '',
    'preflight.py': '',
    'frame1_gate.py': '',
    'likeness_gate.py': '',
    'workflow-i2v-locked.json': '',
    'workflow-turbo-fixed.json': '',
}
# Files where the embedded copy ALWAYS wins (they carry the v3 fixes);
# a differing dataset copy is logged as drift, never silently used.
EMBED_WINS = {'preflight.py', 'workflow-turbo-fixed.json'}

def log(*a): print(' '.join(str(x) for x in a), flush=True)
def sh(cmd, **kw):
    r = subprocess.run(cmd, shell=True, capture_output=True, text=True, **kw)
    if r.stdout: log(r.stdout[-800:])
    if r.returncode != 0 and r.stderr: log('STDERR', r.stderr[-800:])
    return r
def sha(p):
    h = hashlib.sha256()
    with open(p, 'rb') as f:
        for chunk in iter(lambda: f.read(1 << 20), b''): h.update(chunk)
    return h.hexdigest()
def find_input(name):
    """Kaggle datasets only; returns None on other lanes / when absent."""
    hits = sorted(glob.glob(f'/kaggle/input/**/{name}', recursive=True))
    return hits[0] if hits else None

# ---------- report / progress plumbing (from v2) ----------
def flush_report():
    try:
        with open(REPORT_PATH, 'w') as f:
            json.dump(REPORT, f, indent=1)
    except Exception as e:
        log('flush_report failed:', e)

def api_get(path):
    with urllib.request.urlopen(f'http://127.0.0.1:8188{path}', timeout=30) as r:
        return json.loads(r.read())

def tail_lines(path, n=40):
    if not path or not os.path.exists(path):
        return []
    try:
        with open(path, 'rb') as f:
            data = f.read()
        return data.decode('utf-8', errors='replace').splitlines()[-n:]
    except Exception:
        return []

def queue_state():
    try:
        q = api_get('/queue')
        running = q.get('queue_running') or []
        pending = q.get('queue_pending') or []
        return {'running_prompts': [item[1] for item in running if len(item) > 1],
                'running_count': len(running), 'pending_count': len(pending)}
    except Exception as e:
        return {'error': f'{type(e).__name__}: {e}'}

def record_progress(label, t0, entry=None):
    hist_status = None
    if entry:
        st = entry.get('status') or {}
        hist_status = {'status_str': st.get('status_str'), 'completed': st.get('completed')}
    REPORT.setdefault('progress', {})[label] = {
        'elapsed_s': round(time.time() - t0, 1),
        'timeout_s': GRAPH_TIMEOUT,
        'queue': queue_state(),
        'history_status': hist_status,
        'comfy_log_tail': tail_lines(CURRENT_LOG['path']),
        'updated_at': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
    }
    flush_report()

def clone_pinned(url, dest, pin):
    """Clone at a pinned commit; assert the checkout matches the pin."""
    if not os.path.exists(dest):
        assert sh(f'git clone --depth 1 {url} {dest}').returncode == 0, f'clone failed: {url}'
    head = sh(f'git -C {dest} rev-parse HEAD').stdout.strip()
    if head != pin:
        assert sh(f'git -C {dest} fetch --depth 1 origin {pin}').returncode == 0, f'fetch pin failed: {url}'
        assert sh(f'git -C {dest} checkout -q {pin}').returncode == 0, f'checkout pin failed: {url}'
        head = pin
    log('pinned', os.path.basename(dest), head)
    return head

try:
    T0 = time.time()
    try:
        log(sh('nvidia-smi').stdout[:400])
    except Exception as e:
        log('nvidia-smi unavailable:', e)

    # ---------- stage job files (v3: self-contained, sources logged) ----------
    JOB = f'{WORK}/job'; os.makedirs(JOB, exist_ok=True)
    def write_embedded(rel):
        dest = f'{JOB}/{rel}'
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, 'wb') as f:
            f.write(base64.b64decode(EMBED_B64[rel]))
        return dest
    for rel in EMBED_B64:
        name = os.path.basename(rel)
        embedded_path = write_embedded(rel)
        embedded_sha = sha(embedded_path)
        dataset_hit = find_input(name) if LANE == 'kaggle' else None
        # Canon cutouts are looked up by their cutout name in the job tree;
        # dataset overlay does not apply to them (they are new in v3).
        if dataset_hit and name not in EMBED_WINS and not rel.startswith('canon-cutouts/'):
            shutil.copy(dataset_hit, f'{JOB}/{rel}')
            REPORT['staging'][rel] = {'source': 'dataset', 'path': dataset_hit,
                                      'sha256': sha(f'{JOB}/{rel}'), 'embedded_sha256': embedded_sha}
        else:
            REPORT['staging'][rel] = {'source': 'embedded', 'sha256': embedded_sha,
                                      **({'dataset_sha256': sha(dataset_hit),
                                          'dataset_copy_overridden': True} if dataset_hit else {})}
    # Reference manifest: start images from the dataset manifest when the
    # dataset supplied them, else the embedded pins (same hashes).
    MANIFEST = None
    mh = find_input('reference-manifest.json') if LANE == 'kaggle' else None
    if mh:
        shutil.copy(mh, f'{JOB}/reference-manifest.json')
        MANIFEST = json.load(open(f'{JOB}/reference-manifest.json'))
    if not MANIFEST:
        MANIFEST = {'dorowani_start_tight.png': 'aa124c9adc8caacd22628d06f4d1373e16e02e41bfb650028c014a58af0c5720',
                    'wispkin_start_tight.png': '9bff28175fe378b816a8743c6f846ea338d7aeb9a64072ec6610e0c3faa73250'}
        json.dump(MANIFEST, open(f'{JOB}/reference-manifest.json', 'w'), indent=1)
    DORO_SHA = MANIFEST['dorowani_start_tight.png']
    WISP_SHA = MANIFEST['wispkin_start_tight.png']
    assert sha(f'{JOB}/dorowani_start_tight.png') == DORO_SHA, 'dorowani tight reference hash mismatch vs manifest'
    assert sha(f'{JOB}/wispkin_start_tight.png') == WISP_SHA, 'wispkin tight reference hash mismatch vs manifest'
    # Bug 1 fix, belt and braces: the gate reads cutouts from the job copy
    # (--cutouts) AND its own legacy default must resolve too — write the
    # pinned cutouts to the exact path likeness_gate.DEFAULT_CUTOUTS names.
    for cname, csha in CUTOUT_SHA.items():
        src = f'{JOB}/canon-cutouts/{cname}'
        assert sha(src) == csha, f'canon cutout hash mismatch: {cname}'
        legacy = Path.home() / 'workspace' / 'mochiichao-show' / 'canon-cutouts' / cname
        legacy.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy(src, legacy)
        assert sha(str(legacy)) == csha, f'legacy cutout write mismatch: {cname}'
    REPORT['staging']['canon_cutouts'] = {'job_dir': f'{JOB}/canon-cutouts',
                                          'legacy_default_dir': str(Path.home() / 'workspace' / 'mochiichao-show' / 'canon-cutouts'),
                                          'sha256': CUTOUT_SHA}
    REPORT['timings']['stage_job_s'] = round(time.time() - T0, 1)
    flush_report()
    log('job staged (lane:', LANE, '); reference + cutout hashes match pins')

    # ---------- ComfyUI (pinned) ----------
    if not os.path.exists(f'{WORK}/ComfyUI'):
        clone_pinned('https://github.com/comfyanonymous/ComfyUI.git', f'{WORK}/ComfyUI', COMFYUI_PIN)
    else:
        log('ComfyUI already present; pin not re-asserted on a reused checkout')
    sh(f'{sys.executable} -m pip install -q -r {WORK}/ComfyUI/requirements.txt scipy')
    models = f'{WORK}/ComfyUI/models'
    # Non-Kaggle weight sources (verified on Hugging Face, 2026-10-28).
    HF_WEIGHTS = {
        'wan2.1_vace_1.3B_fp16.safetensors': ('Comfy-Org/Wan_2.1_ComfyUI_repackaged', 'split_files/diffusion_models/wan2.1_vace_1.3B_fp16.safetensors'),
        'wan_2.1_vae.safetensors': ('Comfy-Org/Wan_2.1_ComfyUI_repackaged', 'split_files/vae/wan_2.1_vae.safetensors'),
        'umt5_xxl_fp8_e4m3fn_scaled.safetensors': ('Comfy-Org/Wan_2.1_ComfyUI_repackaged', 'split_files/text_encoders/umt5_xxl_fp8_e4m3fn_scaled.safetensors'),
        'wan2.2_ti2v_5B_fp16.safetensors': ('Comfy-Org/Wan_2.2_ComfyUI_Repackaged', 'split_files/diffusion_models/wan2.2_ti2v_5B_fp16.safetensors'),
        'wan2.2_vae.safetensors': ('Comfy-Org/Wan_2.2_ComfyUI_Repackaged', 'split_files/vae/wan2.2_vae.safetensors'),
        'Wan22_TI2V_5B_Turbo_lora_rank_64_fp16.safetensors': ('Kijai/WanVideo_comfy', 'LoRAs/Wan22-Turbo/Wan22_TI2V_5B_Turbo_lora_rank_64_fp16.safetensors'),
    }
    def stage_model(name, sub, expect_size=None):
        dst = f'{models}/{sub}/{name}'
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        if os.path.exists(dst) or os.path.islink(dst): os.unlink(dst)
        src = find_input(name) if LANE == 'kaggle' else None
        if src is None:
            assert name in HF_WEIGHTS, f'no weight source for {name} on lane {LANE}'
            from huggingface_hub import hf_hub_download
            repo, fn = HF_WEIGHTS[name]
            src = hf_hub_download(repo_id=repo, filename=fn)
            log('HF staged', name, 'from', repo)
        os.symlink(src, dst)
        size = os.path.getsize(dst)
        log('staged', name, size)
        if expect_size: assert size == expect_size, f'{name} size {size} != expected {expect_size}'
        return dst
    # Native VACE seat.
    stage_model('wan2.1_vace_1.3B_fp16.safetensors', 'diffusion_models', 4309519800)
    stage_model('wan_2.1_vae.safetensors', 'vae')
    stage_model('umt5_xxl_fp8_e4m3fn_scaled.safetensors', 'text_encoders')  # native loader only

    # ---------- PREFLIGHT (before any GPU work; now incl. channel contract) ----------
    t_pf = time.time()
    pf = sh(f'{sys.executable} {JOB}/preflight.py --workflow {JOB}/workflow-i2v-locked.json --strict-vace '
            f'--reference {JOB}/dorowani_start_tight.png --expected-sha256 {DORO_SHA} '
            f'--out {OUT}/preflight-locked.json')
    assert pf.returncode == 0, 'PREFLIGHT ABORT (locked workflow) — see preflight-locked.json'
    pf2 = sh(f'{sys.executable} {JOB}/preflight.py --workflow {JOB}/workflow-turbo-fixed.json '
             f'--reference {JOB}/dorowani_start_tight.png --expected-sha256 {DORO_SHA} '
             f'--out {OUT}/preflight-turbo.json')
    assert pf2.returncode == 0, 'PREFLIGHT ABORT (turbo workflow) — see preflight-turbo.json'
    REPORT['phases']['preflight'] = 'PASS (locked strict-vace + turbo incl. channel contract)'
    REPORT['timings']['preflight_s'] = round(time.time() - t_pf, 1)
    flush_report()
    log('PREFLIGHT PASS')

    # ---------- server management (v2, plus boot timings) ----------
    shutil.copy(f'{JOB}/dorowani_start_tight.png', f'{WORK}/ComfyUI/input/dorowani_start_tight.png')
    shutil.copy(f'{JOB}/wispkin_start_tight.png', f'{WORK}/ComfyUI/input/wispkin_start_tight.png')
    SRV = {'proc': None}
    def get(path):
        with urllib.request.urlopen(f'http://127.0.0.1:8188{path}', timeout=30) as r: return json.loads(r.read())
    def start_server(logname):
        t_boot = time.time()
        logpath = f'{WORK}/{logname}'
        proc = subprocess.Popen([sys.executable, 'main.py', '--listen', '127.0.0.1', '--port', '8188', '--disable-auto-launch'],
                                cwd=f'{WORK}/ComfyUI', stdout=open(logpath, 'w'), stderr=subprocess.STDOUT)
        SRV['proc'] = proc
        CURRENT_LOG['path'] = logpath
        for _ in range(120):
            try:
                get('/system_stats')
                REPORT['timings'][f'boot_{logname}_s'] = round(time.time() - t_boot, 1)
                log('COMFYUI_UP', logname)
                return
            except Exception: time.sleep(5)
        raise RuntimeError(f'ComfyUI did not come up ({logname})')
    def stop_server():
        proc = SRV['proc']
        if proc is not None:
            proc.terminate()
            try: proc.wait(timeout=60)
            except Exception: proc.kill()
            SRV['proc'] = None
    def ensure_server(logname):
        if SRV['proc'] is None or SRV['proc'].poll() is not None:
            start_server(logname)

    def run_graph(wf, label):
        body = json.dumps({'prompt': wf, 'client_id': f'locked-run-{label}'}).encode()
        req = urllib.request.Request('http://127.0.0.1:8188/prompt', data=body, headers={'Content-Type': 'application/json'})
        pid = json.loads(urllib.request.urlopen(req).read())['prompt_id']
        t0 = time.time()
        last_flush = 0.0
        record_progress(label, t0)
        while time.time() - t0 < GRAPH_TIMEOUT:
            hist = get(f'/history/{pid}')
            entry = hist.get(pid)
            if entry and entry.get('status', {}).get('completed'):
                record_progress(label, t0, entry)
                return pid, time.time() - t0, entry
            if entry and entry.get('status', {}).get('status_str') == 'error':
                record_progress(label, t0, entry)
                raise RuntimeError(f'{label}: execution error: {json.dumps(entry.get("status"))[:600]}')
            if time.time() - last_flush >= PROGRESS_EVERY:
                record_progress(label, t0, entry)
                last_flush = time.time() - t0
            time.sleep(5)
        record_progress(label, t0)
        raise RuntimeError(f'{label}: timed out')

    def find_output(prefix):
        hits = sorted(glob.glob(f'{WORK}/ComfyUI/output/{prefix}*.mp4'))
        assert hits, f'no output for {prefix}'
        return hits[-1]

    def gate(clip, reference, species, tag):
        pkt = f'{OUT}/{tag}_frame1_gate.json'
        r = sh(f'{sys.executable} {JOB}/frame1_gate.py --clip {clip} --reference {reference} '
               f'--species {species} --cutouts {JOB}/canon-cutouts '
               f'--likeness-gate {JOB}/likeness_gate.py '
               f'--scratch {WORK}/gate-scratch-{tag} --out {pkt}')
        d = json.load(open(pkt))
        log('GATE', tag, d['verdict'], d['fail_class'])
        return d

    # ---------- phase 1: TURBO-FIXED run FIRST (wrapper seat) ----------
    try:
        if not os.path.exists(f'{WORK}/ComfyUI/custom_nodes/ComfyUI-WanVideoWrapper'):
            clone_pinned('https://github.com/kijai/ComfyUI-WanVideoWrapper.git',
                         f'{WORK}/ComfyUI/custom_nodes/ComfyUI-WanVideoWrapper', WRAPPER_PIN)
            sh(f'{sys.executable} -m pip install -q -r {WORK}/ComfyUI/custom_nodes/ComfyUI-WanVideoWrapper/requirements.txt')
        REPORT['pins'] = {'comfyui': COMFYUI_PIN, 'wanvideowrapper': WRAPPER_PIN}
        stage_model('wan2.2_ti2v_5B_fp16.safetensors', 'diffusion_models')
        stage_model('wan2.2_vae.safetensors', 'vae')
        stage_model('Wan22_TI2V_5B_Turbo_lora_rank_64_fp16.safetensors', 'loras')
        # Non-scaled UMT5: the fix file. Size-verify, then header-verify via preflight.
        from huggingface_hub import hf_hub_download
        p = hf_hub_download(repo_id='Kijai/WanVideo_comfy', filename='umt5-xxl-enc-fp8_e4m3fn.safetensors')
        t5_dst = f'{models}/text_encoders/umt5-xxl-enc-fp8_e4m3fn.safetensors'
        shutil.copy(p, t5_dst)
        size = os.path.getsize(t5_dst)
        assert size == 6731333792, f'non-scaled UMT5 size {size} != 6731333792'
        REPORT['phases']['umt5_stage'] = {'bytes': size, 'sha256': sha(t5_dst)}
        flush_report()
        pf3 = sh(f'{sys.executable} {JOB}/preflight.py --workflow {JOB}/workflow-turbo-fixed.json '
                 f'--reference {JOB}/dorowani_start_tight.png --expected-sha256 {DORO_SHA} '
                 f'--t5-file {t5_dst} --out {OUT}/preflight-turbo-t5file.json')
        assert pf3.returncode == 0, 'PREFLIGHT ABORT (turbo + actual T5 file)'
        # Boot (or restart) the server so the wrapper nodes load.
        if SRV['proc'] is not None:
            stop_server()
            start_server('comfy-turbo.log')
        else:
            start_server('comfy-turbo.log')
        wf_t = json.load(open(f'{JOB}/workflow-turbo-fixed.json'))
        pid, secs, hist = run_graph(wf_t, 'turbo')
        json.dump(hist, open(f'{OUT}/history-turbo.json', 'w'), indent=1)
        submitted = hist.get('prompt', [None, None, {}])[2] or {}
        lora_wire = submitted.get('3', {}).get('inputs', {}).get('lora')
        clip = find_output('turbo_fixed_dorowani')
        dst = f'{OUT}/turbo_fixed_dorowani.mp4'; shutil.copy(clip, dst)
        g = gate(dst, f'{JOB}/dorowani_start_tight.png', 'dorowani', 'turbo')
        REPORT['phases']['turbo'] = {'seconds': round(secs, 1), 'lora_wire_in_history': lora_wire,
                                     'clip': os.path.basename(dst), 'bytes': os.path.getsize(dst), 'sha256': sha(dst),
                                     'gate_verdict': g['verdict'], 'fail_class': g['fail_class'],
                                     'frame0_canon': g.get('canon_cutout_results', {}).get('0')}
        log('TURBO DONE', REPORT['phases']['turbo'])
    except Exception as e:
        REPORT['phases']['turbo'] = {'error': f'{type(e).__name__}: {e}'}
        log('TURBO PHASE FAILED (recorded, remaining phases still run):', e)
    flush_report()

    # ---------- phase 2: LOCKED run ----------
    try:
        ensure_server('comfy-locked.log')
        wf = json.load(open(f'{JOB}/workflow-i2v-locked.json'))
        pid, secs, hist = run_graph(wf, 'locked')
        submitted = hist.get('prompt', [None, None, {}])[2] or {}
        audit = {
            'node7_reference_image': submitted.get('7', {}).get('inputs', {}).get('reference_image'),
            'node1_unet': submitted.get('1', {}).get('inputs', {}).get('unet_name'),
            'node10_trim_amount': submitted.get('10', {}).get('inputs', {}).get('trim_amount'),
        }
        audit_ok = (audit['node7_reference_image'] == ['6', 0]
                    and audit['node1_unet'] == 'wan2.1_vace_1.3B_fp16.safetensors'
                    and audit['node10_trim_amount'] == ['7', 3])
        json.dump(hist, open(f'{OUT}/history-locked.json', 'w'), indent=1)
        clip = find_output('locked_i2v_dorowani')
        dst = f'{OUT}/locked_i2v_dorowani.mp4'; shutil.copy(clip, dst)
        g = gate(dst, f'{JOB}/dorowani_start_tight.png', 'dorowani', 'locked')
        REPORT['phases']['locked'] = {'seconds': round(secs, 1), 'history_audit': audit, 'audit_ok': audit_ok,
                                      'clip': os.path.basename(dst), 'bytes': os.path.getsize(dst), 'sha256': sha(dst),
                                      'gate_verdict': g['verdict'], 'fail_class': g['fail_class'],
                                      'frame0_canon': g.get('canon_cutout_results', {}).get('0')}
        if not audit_ok:
            REPORT['phases']['locked']['audit_failure'] = ('HISTORY AUDIT FAILED — the submitted graph that '
                                                          'actually ran does not carry the lock wires; the '
                                                          'likeness-lock claim for this clip is DEAD.')
            log('LOCKED HISTORY AUDIT FAILED (recorded):', audit)
        log('LOCKED DONE', REPORT['phases']['locked'])
    except Exception as e:
        REPORT['phases']['locked'] = {'error': f'{type(e).__name__}: {e}'}
        log('LOCKED PHASE FAILED (recorded, control still runs):', e)
    flush_report()

    # ---------- phase 3: negative control (reference swapped to Wispkin) ----------
    try:
        ensure_server('comfy-control.log')
        wf_c = json.load(open(f'{JOB}/workflow-i2v-locked.json'))
        wf_c['6']['inputs']['image'] = 'wispkin_start_tight.png'
        wf_c['13']['inputs']['filename_prefix'] = 'locked_control_wispkin'
        pid, secs, hist = run_graph(wf_c, 'control')
        json.dump(hist, open(f'{OUT}/history-control.json', 'w'), indent=1)
        clip = find_output('locked_control_wispkin')
        dst = f'{OUT}/locked_control_wispkin.mp4'; shutil.copy(clip, dst)
        g_w = gate(dst, f'{JOB}/wispkin_start_tight.png', 'wispkin', 'control_vs_wispkin')
        g_d = gate(dst, f'{JOB}/dorowani_start_tight.png', 'dorowani', 'control_vs_dorowani')
        # Control works iff frame 1 follows Wispkin (its fed reference) better
        # than Dorowani on the fed-reference SSIM.
        s_w = g_w.get('fed_reference_results', {}).get('0', {}).get('measurements', {}).get('ssim_union')
        s_d = g_d.get('fed_reference_results', {}).get('0', {}).get('measurements', {}).get('ssim_union')
        REPORT['phases']['negative_control'] = {'seconds': round(secs, 1), 'clip': os.path.basename(dst),
                                                'sha256': sha(dst), 'frame0_ssim_vs_wispkin_ref': s_w,
                                                'frame0_ssim_vs_dorowani_ref': s_d,
                                                'control_follows_reference': (s_w is not None and s_d is not None and s_w > s_d)}
        log('CONTROL DONE', REPORT['phases']['negative_control'])
    except Exception as e:
        REPORT['phases']['negative_control'] = {'error': f'{type(e).__name__}: {e}'}
        log('CONTROL PHASE FAILED (recorded):', e)
    flush_report()

    REPORT['status'] = 'DONE'
    REPORT['timings']['total_s'] = round(time.time() - T0, 1)
except Exception:
    REPORT['status'] = 'FAILED'
    REPORT['exception'] = traceback.format_exc()
    log('KERNEL_EXCEPTION\n', REPORT['exception'])
finally:
    flush_report()
    log('REPORT', json.dumps(REPORT)[:1500])
    log('LOCKED_RUN_KERNEL_DONE')
